using System;
using System.Collections.Generic;
using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Mirrors recent Unity console messages in the host UI and forwards them to connected
/// researcher dashboards over the network bridge.
///
/// Forwarding is best-effort diagnostics: messages are queued (bounded, oldest dropped first),
/// sent at a capped rate per frame, and never generated by the forwarder's own sends, so a
/// log burst or a failing send cannot turn into a feedback loop or stall the XR frame.
/// </summary>
public class ConsoleToHost_And_ClientUILogger : MonoBehaviour
{
    [SerializeField] private TMP_Text _logText;
    [SerializeField, Min(1)] private int _maxLines = 10;
    [SerializeField] private ScrollRect _scrollRect;

    [Header("Forwarding limits")]
    [SerializeField, Min(1)] private int maxForwardedPerFrame = 5;
    [SerializeField, Min(1)] private int maxPendingForwards = 200;

    // Retained for compatibility with other scene components that inspect this flag.
    public bool canForwardLogs;

    private readonly Queue<string> _logQueue = new Queue<string>();
    private readonly Queue<string> pendingForwards = new Queue<string>();
    private readonly HashSet<ulong> connectedDashboardClients = new HashSet<ulong>();
    private NetworkSharedLogic networkSharedLogic;
    private NetworkManager manager;
    private bool displayDirty;
    private bool isFlushing;
    private int droppedForwards;

    private void OnEnable()
    {
        Application.logMessageReceived += HandleLog;
        manager = NetworkManager.Singleton;
        if (manager == null) return;
        manager.OnServerStarted += ListenForConnectedClients;
        if (manager.IsServer) ListenForConnectedClients();
    }

    private void OnDisable()
    {
        Application.logMessageReceived -= HandleLog;
        if (manager != null)
        {
            manager.OnServerStarted -= ListenForConnectedClients;
            manager.OnClientConnectedCallback -= OnClientConnected;
            manager.OnClientDisconnectCallback -= OnClientDisconnected;
        }
        connectedDashboardClients.Clear();
        pendingForwards.Clear();
        droppedForwards = 0;
        canForwardLogs = false;
        networkSharedLogic = null;
    }

    private void ListenForConnectedClients()
    {
        if (manager == null || !manager.IsServer) return;
        // Re-subscribing is safe, even if initialization fires twice.
        manager.OnClientConnectedCallback -= OnClientConnected;
        manager.OnClientDisconnectCallback -= OnClientDisconnected;
        manager.OnClientConnectedCallback += OnClientConnected;
        manager.OnClientDisconnectCallback += OnClientDisconnected;
        connectedDashboardClients.Clear();
        foreach (ulong id in manager.ConnectedClientsIds)
            if (id != manager.ServerClientId) connectedDashboardClients.Add(id);
        UpdateForwardingState();
    }

    private void OnClientConnected(ulong clientId)
    {
        if (manager == null || clientId == manager.ServerClientId) return;
        connectedDashboardClients.Add(clientId);
        UpdateForwardingState();
        EnqueueForward($"[{DateTime.Now:HH:mm:ss}] [INFO] Researcher dashboard connected.");
    }

    private void OnClientDisconnected(ulong clientId)
    {
        connectedDashboardClients.Remove(clientId);
        UpdateForwardingState();
    }

    private void UpdateForwardingState()
    {
        canForwardLogs = manager != null && manager.IsServer && connectedDashboardClients.Count > 0;
        if (!canForwardLogs) networkSharedLogic = null;
    }

    private void HandleLog(string message, string stackTrace, LogType type)
    {
        string color = type == LogType.Error || type == LogType.Exception ? "red" :
                       type == LogType.Warning ? "yellow" : "white";
        string formatted = $"<color={color}>[{DateTime.Now:HH:mm:ss}] [{type}] {message}</color>";
        while (_logQueue.Count >= Mathf.Max(1, _maxLines)) _logQueue.Dequeue();
        _logQueue.Enqueue(formatted);
        displayDirty = true;   // the text is rebuilt once per frame, not once per message

        // Anything logged while the forwarder itself is sending is shown locally only.
        if (canForwardLogs && !isFlushing) EnqueueForward(formatted);
    }

    private void LateUpdate()
    {
        if (displayDirty)
        {
            displayDirty = false;
            if (_logText != null) _logText.text = string.Join("\n", _logQueue);
            if (_scrollRect != null) _scrollRect.verticalNormalizedPosition = 0f;
        }
        FlushForwards();
    }

    /// <summary>Write through the standard Unity logger, which calls HandleLog.</summary>
    public static void LogToUI(string message) => Debug.Log(message);

    private void EnqueueForward(string formatted)
    {
        if (!canForwardLogs) return;
        while (pendingForwards.Count >= Mathf.Max(1, maxPendingForwards))
        {
            pendingForwards.Dequeue();
            droppedForwards++;
        }
        pendingForwards.Enqueue(formatted);
    }

    private void FlushForwards()
    {
        if (pendingForwards.Count == 0 && droppedForwards == 0) return;
        if (!canForwardLogs || manager == null || !manager.IsServer)
        {
            pendingForwards.Clear();
            droppedForwards = 0;
            return;
        }
        // The network prefab can spawn later than the client-connect callback; keep the
        // (bounded) queue until it is available.
        if (!TryResolveBridge()) return;

        isFlushing = true;
        try
        {
            if (droppedForwards > 0)
            {
                networkSharedLogic.SendLogToClientClientRpc(
                    $"<color=yellow>[{DateTime.Now:HH:mm:ss}] [Warning] {droppedForwards} log line(s) were dropped by the forwarder.</color>");
                droppedForwards = 0;
            }
            for (int i = 0; i < Mathf.Max(1, maxForwardedPerFrame) && pendingForwards.Count > 0; i++)
                networkSharedLogic.SendLogToClientClientRpc(pendingForwards.Dequeue());
        }
        finally
        {
            isFlushing = false;
        }
    }

    private bool TryResolveBridge()
    {
        if (networkSharedLogic != null && networkSharedLogic.IsSpawned) return true;
        GameObject player = GameObject.FindGameObjectWithTag(NetworkSharedLogic.BridgeTag);
        networkSharedLogic = player != null ? player.GetComponent<NetworkSharedLogic>() : null;
        return networkSharedLogic != null && networkSharedLogic.IsSpawned;
    }
}
